class QueueByStack:
    def __init__(self):
        self.in_st = []
        self.out_st = []
    def push(self, x):
        self.in_st.append(x)
    def pop(self):
        self._move()
        return self.out_st.pop()
    def _move(self):
        if not self.out_st:
            while self.in_st:
                self.out_st.append(self.in_st.pop())
思路：两个栈，出队时把入栈倒到出栈。均摊O(1)。

def majority(nums):
    cand = None
    count = 0
    for x in nums:
        if count == 0:
            cand = x
            count = 1
        elif x == cand:
            count += 1
        else:
            count -= 1
    return cand
思路：摩尔投票法。复杂度O(n)，空间O(1)。
